import React from "react";
import Link from "next/link";
import { Metadata } from "next";
import { CATEGORIES } from "@/data/categories";
import { getAllTools } from "@/data/tools";
import { Navbar } from "@/components/navigation/Navbar";
import { Footer } from "@/components/footer/Footer";
import {
  Image as ImageIcon,
  FileText,
  Code2,
  Type,
  Calculator,
  Share2,
  LayoutGrid,
  ArrowRight,
  LucideIcon,
} from "lucide-react";

export const metadata: Metadata = {
  title: "Tool Categories — Browse All Utilities",
  description:
    "Explore Zorli tools by category: Image, PDF, Developer, Text, Calculator, and Social media utilities.",
};

const CATEGORY_ICONS: Record<string, LucideIcon> = {
  Image: ImageIcon,
  FileText: FileText,
  Code2: Code2,
  Type: Type,
  Calculator: Calculator,
  Share2: Share2,
  LayoutGrid: LayoutGrid,
};

export default function CategoriesOverviewPage() {
  const allTools = getAllTools();

  return (
    <div className="flex flex-col min-h-screen bg-[#070B24]">
      <Navbar />

      <main className="flex-1 w-full pt-32 pb-24">
        {/* Header */}
        <section className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center text-white mb-16">
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-white/10 border border-white/15 text-xs font-semibold uppercase tracking-widest text-indigo-300 mb-4 backdrop-blur-md">
            Categories
          </div>
          <h1 className="text-4xl sm:text-5xl font-extrabold tracking-tight mb-4">
            Explore by{" "}
            <span className="text-gradient-hero">Category</span>
          </h1>
          <p className="text-base sm:text-lg text-white/70 max-w-xl mx-auto">
            Discover simple, private, browser-based online tools structured logically for your daily workflow.
          </p>
        </section>

        {/* Categories Grid Container */}
        <section className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {CATEGORIES.map((category) => {
              const Icon = CATEGORY_ICONS[category.iconName] || LayoutGrid;
              const toolsInCat = allTools.filter(
                (t) => t.category.toLowerCase() === category.slug.toLowerCase()
              );

              return (
                <Link
                  key={category.id}
                  href={category.id === "more" ? "/tools" : `/categories/${category.slug}`}
                  className="group flex flex-col justify-between p-6 sm:p-8 bg-[#0D1438]/80 hover:bg-[#15164A] rounded-3xl border border-white/10 hover:border-indigo-400/40 shadow-xl transition-all duration-300 hover:-translate-y-1"
                >
                  <div>
                    <div
                      className={`w-14 h-14 rounded-2xl flex items-center justify-center mb-6 bg-gradient-to-br ${category.bgGradient} ${category.iconColor} border border-white/10 group-hover:scale-110 transition-transform duration-300`}
                    >
                      <Icon className="w-7 h-7" />
                    </div>

                    <h2 className="text-2xl font-bold text-white group-hover:text-indigo-300 transition-colors mb-2">
                      {category.name}
                    </h2>

                    <p className="text-sm text-white/70 leading-relaxed mb-4">
                      {category.description}
                    </p>
                  </div>

                  <div className="pt-4 border-t border-white/10 flex items-center justify-between text-xs text-indigo-300 font-medium">
                    <span>{toolsInCat.length > 0 ? `${toolsInCat.length} tools available` : category.toolCountNotice}</span>
                    <div className="w-8 h-8 rounded-full bg-white/10 flex items-center justify-center text-white group-hover:bg-indigo-600 transition-colors">
                      <ArrowRight className="w-4 h-4 transform group-hover:translate-x-0.5 transition-transform" />
                    </div>
                  </div>
                </Link>
              );
            })}
          </div>
        </section>
      </main>

      <Footer />
    </div>
  );
}
