export function getAllTools(): Tool[] {
  return TOOLS_REGISTRY;
}

export function getToolsByCategory(categorySlug: string): Tool[] {
  return TOOLS_REGISTRY.filter(
    (t) => t.category.toLowerCase() === categorySlug.toLowerCase()
  );
}

export function getToolBySlug(slug: string): Tool | undefined {
  return TOOLS_REGISTRY.find((t) => t.slug.toLowerCase() === slug.toLowerCase());
}

export function getPopularTools(limit = 6): Tool[] {
  return TOOLS_REGISTRY.filter((t) => t.popular).slice(0, limit);
}

export function getRelatedTools(currentTool: Tool, limit = 3): Tool[] {
  return TOOLS_REGISTRY.filter(
    (t) => t.category === currentTool.category && t.slug !== currentTool.slug
  ).slice(0, limit);
}

export function searchTools(query: string): Tool[] {
  const clean = query.trim().toLowerCase();
  if (!clean) return [];
  return TOOLS_REGISTRY.filter(
    (t) =>
      t.name.toLowerCase().includes(clean) ||
      t.description.toLowerCase().includes(clean) ||
      t.tags.some((tag) => tag.toLowerCase().includes(clean))
  );
}
